// EVENT SOURCING — when simple audit log isn't enough:
// ACCOUNT ENTITY: no mutable state, only events!

@Entity @Table(name = "account_events")
public class AccountEvent {
    private Long accountId;
    private Long version;        // sequence number per account
    private String eventType;    // 'AccountOpened', 'MoneyDeposited', etc.
    private JSONB payload;       // event-specific data
    private Instant occurredAt;
    // Never UPDATE or DELETE rows in this table!
}

// CURRENT STATE = replay all events:
public Account loadAccount(Long accountId) {
    List<AccountEvent> events = eventRepo.findByAccountId(accountId);
    Account account = new Account(); // empty
    for (AccountEvent event : events) {
        account.apply(event);  // state machine: each event transitions state
    }
    return account;
}

// TEMPORAL QUERY: state at specific point in time
public Account loadAccountAt(Long accountId, Instant pointInTime) {
    List<AccountEvent> events = eventRepo
        .findByAccountIdAndOccurredAtBefore(accountId, pointInTime);
    // Replay only events before that timestamp
    return replay(events);
}

// PERFORMANCE: Snapshots for long-lived aggregates
// Instead of replaying all 10,000 events:
// Load last snapshot (e.g., at event #9900)
// Replay only last 100 events from that point
@Entity @Table(name = "account_snapshots")
public class AccountSnapshot {
    private Long accountId;
    private Long atVersion;  // event sequence number
    private JSONB state;     // serialized account state at this version
    private Instant createdAt;
}
